// Shared UI strings. Static copy lives in the English pages and /es/; this file
// covers the text generated by JS (galleries, lightbox, videos, signup, theme).
(() => {
  const LANG = document.documentElement.lang === 'es' ? 'es' : 'en';

  const STRINGS = {
    en: {
      'theme.dark': 'Switch to dark mode',
      'theme.light': 'Switch to light mode',
      'signup.title': 'Stay in the loop',
      'signup.body': 'New photos and videos, now and then. No spam.',
      'signup.email': 'Email address',
      'signup.subscribe': 'Subscribe',
      'signup.close': 'Close',
      'signup.invalid': 'Please enter a valid email address.',
      'signup.subscribing': 'Subscribing…',
      'signup.success': 'Thanks — you’re on the list.',
      'signup.error': 'Something went wrong. Please try again.',
      'signup.network': 'Network error. Please try again.',
      'signup.subject': 'New newsletter signup',
      'photos.title': 'Photos — ethan close',
      'photos.albumTitle': '{title} — ethan close',
      'photos.empty': 'No albums yet.',
      'photos.error': 'Could not load photos.',
      'photos.all': 'All albums',
      'photos.photo': 'photo',
      'photos.photos': 'photos',
      'photos.open': 'Open photo {n} of {total}',
      'photos.alt': '{title} — photo {n}',
      'photos.viewer': '{title} photo viewer',
      'lightbox.zoomOut': 'Zoom out',
      'lightbox.zoomIn': 'Zoom in',
      'lightbox.close': 'Close',
      'lightbox.prev': 'Previous photo',
      'lightbox.next': 'Next photo',
      'videos.empty': 'No videos yet.',
      'videos.error': 'Could not load videos.',
      'videos.play': 'Play {title}',
      'videos.close': 'Close video',
      'videos.youtube': 'Watch on YouTube ↗',
    },
    es: {
      'theme.dark': 'Cambiar al modo oscuro',
      'theme.light': 'Cambiar al modo claro',
      'signup.title': 'Mantente al tanto',
      'signup.body': 'Fotos y videos nuevos, de vez en cuando. Sin spam.',
      'signup.email': 'Correo electrónico',
      'signup.subscribe': 'Suscribirse',
      'signup.close': 'Cerrar',
      'signup.invalid': 'Introduce un correo electrónico válido.',
      'signup.subscribing': 'Suscribiendo…',
      'signup.success': 'Gracias, ya estás en la lista.',
      'signup.error': 'Algo salió mal. Inténtalo de nuevo.',
      'signup.network': 'Error de red. Inténtalo de nuevo.',
      'signup.subject': 'Nueva suscripción al boletín',
      'photos.title': 'Fotos — ethan close',
      'photos.albumTitle': '{title} — ethan close',
      'photos.empty': 'No hay álbumes todavía.',
      'photos.error': 'No se pudieron cargar las fotos.',
      'photos.all': 'Todos los álbumes',
      'photos.photo': 'foto',
      'photos.photos': 'fotos',
      'photos.open': 'Abrir foto {n} de {total}',
      'photos.alt': '{title} — foto {n}',
      'photos.viewer': 'Visor de fotos de {title}',
      'lightbox.zoomOut': 'Alejar',
      'lightbox.zoomIn': 'Acercar',
      'lightbox.close': 'Cerrar',
      'lightbox.prev': 'Foto anterior',
      'lightbox.next': 'Foto siguiente',
      'videos.empty': 'No hay videos todavía.',
      'videos.error': 'No se pudieron cargar los videos.',
      'videos.play': 'Reproducir {title}',
      'videos.close': 'Cerrar video',
      'videos.youtube': 'Ver en YouTube ↗',
    },
  };

  // Display names only: folder names, query strings and the videos data file stay
  // in English so links and data sources keep working in either language.
  const ALBUM_TITLES = {
    es: {
      'Night Heron': 'Garza Nocturna',
    },
  };

  const VIDEO_TITLES = {
    es: {
      'cedar waxwing': 'ampelis americano',
      'Crows over Alcatraz': 'Cuervos sobre Alcatraz',
      'redwood trim': 'poda de la secuoya',
    },
  };

  const dict = STRINGS[LANG];
  const fallback = STRINGS.en;

  function t(key, vars) {
    let value = dict[key] ?? fallback[key] ?? key;
    if (vars) {
      for (const [name, replacement] of Object.entries(vars)) {
        value = value.split(`{${name}}`).join(replacement);
      }
    }
    return value;
  }

  const albumTitle = (title) => (LANG === 'es' && ALBUM_TITLES.es[title]) || title;
  const videoTitle = (title) => (LANG === 'es' && VIDEO_TITLES.es[title]) || title;

  window.EC_I18N = { lang: LANG, t, albumTitle, videoTitle };
})();
